<script setup lang="ts">
import { onMounted, ref, computed } from 'vue'; import { ElMessage, ElMessageBox } from 'element-plus'; import * as api from '@/api/category'; import type { DeviceCategory } from '@/types/category'
const rows=ref<DeviceCategory[]>([]), q=ref(''), loading=ref(false), dialog=ref(false), editing=ref(false), form=ref<DeviceCategory>({categoryId:0,categoryName:'',categoryDesc:''})
const filtered=computed(()=>rows.value.filter(x=>x.categoryName.includes(q.value))); async function load(){loading.value=true;try{rows.value=await api.getCategories()}finally{loading.value=false}} function open(row?:DeviceCategory){editing.value=!!row;form.value=row?{...row}:{categoryId:0,categoryName:'',categoryDesc:''};dialog.value=true} async function save(){if(!form.value.categoryName.trim())return ElMessage.warning('请输入分类名称');const ok=editing.value?await api.updateCategory(form.value.categoryId,form.value):await api.createCategory(form.value);if(ok!==false){ElMessage.success('保存成功');dialog.value=false;load()}} async function remove(row:DeviceCategory){await ElMessageBox.confirm(`确定删除“${row.categoryName}”吗？`,'提示',{type:'warning'});if(await api.deleteCategory(row.categoryId)){ElMessage.success('删除成功');load()}} onMounted(load)
</script>
<template><div class="page"><div class="page-header"><h2>设备分类</h2><el-button type="primary" @click="open()">新增分类</el-button></div><div class="card"><div class="filters"><el-input v-model="q" clearable placeholder="搜索分类名称" style="max-width:280px"/></div><el-table :data="filtered" v-loading="loading" empty-text="暂无数据"><el-table-column prop="categoryName" label="分类名称"/><el-table-column prop="categoryDesc" label="分类描述"/><el-table-column label="操作" width="180"><template #default="{row}"><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" @click="remove(row)">删除</el-button></template></el-table-column></el-table></div><el-dialog v-model="dialog" :title="editing?'编辑分类':'新增分类'" width="480px"><el-form label-width="90px"><el-form-item label="分类名称"><el-input v-model="form.categoryName"/></el-form-item><el-form-item label="分类描述"><el-input v-model="form.categoryDesc" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
